import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { listQuotes, getQuote, createQuote, updateQuote, deleteQuote, submitQuote, approveQuote, sendQuote, respondQuote, cloneQuote } from "@/lib/api";

export function useQuotes(projectId: string, page = 1, pageSize = 20) {
  return useQuery({
    queryKey: ["quotes", projectId, page, pageSize],
    queryFn: () => listQuotes(projectId, { page, page_size: pageSize }),
  });
}

export function useQuote(quoteId: string) {
  return useQuery({
    queryKey: ["quote", quoteId],
    queryFn: () => getQuote(quoteId),
    enabled: !!quoteId,
  });
}

export function useCreateQuote() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ projectId, ...payload }: { projectId: string; boq_id: string; markup_percent?: number; tax_percent?: number; terms?: string; validity_days?: number }) =>
      createQuote(projectId, payload),
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ["quotes", variables.projectId] });
    },
  });
}

export function useUpdateQuote() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ quoteId, projectId, ...payload }: { quoteId: string; projectId: string } & Partial<Parameters<typeof updateQuote>[1]>) =>
      updateQuote(quoteId, payload),
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ["quote", variables.quoteId] });
      queryClient.invalidateQueries({ queryKey: ["quotes", variables.projectId] });
    },
  });
}

export function useDeleteQuote() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ quoteId, projectId }: { quoteId: string; projectId: string }) =>
      deleteQuote(quoteId),
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ["quotes", variables.projectId] });
    },
  });
}

export function useSubmitQuote() {
  return useMutation({
    mutationFn: ({ quoteId, projectId }: { quoteId: string; projectId: string }) =>
      submitQuote(quoteId),
  });
}

export function useApproveQuote() {
  return useMutation({
    mutationFn: ({ quoteId, projectId }: { quoteId: string; projectId: string }) =>
      approveQuote(quoteId),
  });
}

export function useSendQuote() {
  return useMutation({
    mutationFn: ({ quoteId, projectId }: { quoteId: string; projectId: string }) =>
      sendQuote(quoteId),
  });
}

export function useRespondQuote() {
  return useMutation({
    mutationFn: ({ quoteId, projectId, response, notes }: { quoteId: string; projectId: string; response: "accepted" | "rejected"; notes?: string }) =>
      respondQuote(quoteId, { response, notes }),
  });
}

export function useCloneQuote() {
  return useMutation({
    mutationFn: ({ quoteId, projectId }: { quoteId: string; projectId: string }) =>
      cloneQuote(quoteId),
  });
}

import { useState } from "react";
import { useUploadBoq } from "@/hooks/useBoqs";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";

interface BOQUploadProps {
  projectId: string;
}

export function BOQUpload({ projectId }: BOQUploadProps) {
  const [file, setFile] = useState<File | null>(null);
  const [notes, setNotes] = useState("");
  const uploadMutation = useUploadBoq();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!file) return;
    await uploadMutation.mutateAsync({ projectId, file, notes });
    setFile(null);
    setNotes("");
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle>Upload BOQ</CardTitle>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="boq-file">BOQ File (.xlsx, .json)</Label>
            <Input
              id="boq-file"
              type="file"
              accept=".xlsx,.json"
              onChange={(e) => setFile(e.target.files?.[0] ?? null)}
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="boq-notes">Notes (optional)</Label>
            <Textarea
              id="boq-notes"
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              placeholder="Add notes about this BOQ version..."
            />
          </div>
          <Button type="submit" disabled={!file || uploadMutation.isPending}>
            {uploadMutation.isPending ? "Uploading..." : "Upload BOQ"}
          </Button>
          {uploadMutation.isError && (
            <p className="text-sm text-red-500">Upload failed. Please try again.</p>
          )}
        </form>
      </CardContent>
    </Card>
  );
}

import { useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useBoqs } from "@/hooks/useBoqs";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
