import { useState, useEffect } from "react";
import { useQuery } from "@tanstack/react-query";
import { useBoqs } from "@/hooks/useBoqs";
import { useCreateQuote } from "@/hooks/useQuotes";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { getBoqItems } from "@/lib/api";

interface QuoteBuilderProps {
  projectId: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onCreated?: (quoteId: string) => void;
}

export function QuoteBuilder({ projectId, open, onOpenChange, onCreated }: QuoteBuilderProps) {
  const [boqId, setBoqId] = useState("");
  const [markupPercent, setMarkupPercent] = useState(15);
  const [taxPercent, setTaxPercent] = useState(18);
  const [terms, setTerms] = useState("");
  const [validityDays, setValidityDays] = useState(30);
  const [items, setItems] = useState<any[]>([]);
  const [customRates, setCustomRates] = useState<Record<string, number>>({});
  const createMutation = useCreateQuote();
  const { data: boqsData } = useBoqs(projectId, 1, 100);

  useEffect(() => {
    if (!boqId) { setItems([]); return; }
    getBoqItems(boqId).then((d) => {
      setItems(d.items);
      const rates: Record<string, number> = {};
      d.items.forEach((i: any) => { rates[i.id] = i.rate; });
      setCustomRates(rates);
    });
  }, [boqId]);

  const subtotal = items.reduce((sum, item) => sum + (customRates[item.id] ?? item.rate) * item.quantity, 0);
  const markupAmount = subtotal * (markupPercent / 100);
  const afterMarkup = subtotal + markupAmount;
  const taxAmount = afterMarkup * (taxPercent / 100);
  const total = afterMarkup + taxAmount;

  const handleCreate = async () => {
    const quote = await createMutation.mutateAsync({
      projectId,
      boq_id: boqId,
      markup_percent: markupPercent,
      tax_percent: taxPercent,
      terms,
      validity_days: validityDays,
    });
    onOpenChange(false);
    onCreated?.(quote.id);
  };

  const updateRate = (itemId: string, rate: number) => {
    setCustomRates((prev) => ({ ...prev, [itemId]: rate }));
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Create Quote from BOQ</DialogTitle>
        </DialogHeader>
        <div className="space-y-6">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>BOQ Version</Label>
              <select
                className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm"
                value={boqId}
                onChange={(e) => setBoqId(e.target.value)}
              >
                <option value="">Select BOQ version...</option>
                {boqsData?.items.map((boq) => (
                  <option key={boq.id} value={boq.id}>
                    v{boq.version_number} — {boq.file_name}
                  </option>
                ))}
              </select>
            </div>
            <div className="space-y-2">
              <Label>Validity (days)</Label>
              <Input type="number" value={validityDays} onChange={(e) => setValidityDays(Number(e.target.value))} />
            </div>
          </div>
          <div className="grid grid-cols-3 gap-4">
            <div className="space-y-2">
              <Label>Markup %</Label>
              <Input type="number" value={markupPercent} onChange={(e) => setMarkupPercent(Number(e.target.value))} />
            </div>
            <div className="space-y-2">
              <Label>Tax %</Label>
              <Input type="number" value={taxPercent} onChange={(e) => setTaxPercent(Number(e.target.value))} />
            </div>
          </div>
          <div className="space-y-2">
            <Label>Terms & Conditions</Label>
            <Textarea value={terms} onChange={(e) => setTerms(e.target.value)} placeholder="Enter terms..." />
          </div>

          {items.length > 0 && (
            <>
              <div className="rounded-md border overflow-auto max-h-64">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Line</TableHead>
                      <TableHead>Description</TableHead>
                      <TableHead>Unit</TableHead>
                      <TableHead className="text-right">Qty</TableHead>
                      <TableHead className="text-right">Rate</TableHead>
                      <TableHead className="text-right">Amount</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {items.map((item) => (
                      <TableRow key={item.id}>
                        <TableCell>{item.line_number}</TableCell>
                        <TableCell>{item.description}</TableCell>
                        <TableCell>{item.unit}</TableCell>
                        <TableCell className="text-right">{item.quantity}</TableCell>
                        <TableCell className="text-right">
                          <Input
                            type="number"
                            className="w-24 text-right"
                            value={customRates[item.id] ?? item.rate}
                            onChange={(e) => updateRate(item.id, Number(e.target.value))}
                          />
                        </TableCell>
                        <TableCell className="text-right">
                          ₹{((customRates[item.id] ?? item.rate) * item.quantity).toLocaleString()}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>

              <Card>
                <CardContent className="space-y-2">
                  <div className="flex justify-between"><span>Subtotal</span><span>₹{subtotal.toLocaleString()}</span></div>
                  <div className="flex justify-between"><span>Markup ({markupPercent}%)</span><span>₹{markupAmount.toLocaleString()}</span></div>
                  <div className="flex justify-between"><span>Tax ({taxPercent}%)</span><span>₹{taxAmount.toLocaleString()}</span></div>
                  <div className="flex justify-between font-bold text-lg border-t pt-2"><span>Total</span><span>₹{total.toLocaleString()}</span></div>
                </CardContent>
              </Card>
            </>
          )}

          <div className="flex justify-end gap-3">
            <Button variant="outline" onClick={() => onOpenChange(false)}>Cancel</Button>
            <Button onClick={handleCreate} disabled={!boqId || items.length === 0 || createMutation.isPending}>
              {createMutation.isPending ? "Creating..." : "Create Quote"}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { Button } from "@/components/ui/button";
import { useAuth } from "@/hooks/useAuth";
import { useSubmitQuote, useApproveQuote, useSendQuote, useRespondQuote, useCloneQuote } from "@/hooks/useQuotes";
import { Quote } from "@/types/api";
import { downloadQuotePdf } from "@/lib/api";

interface QuoteActionsProps {
  quote: Quote;
  projectId: string;
  onQuoteUpdate?: () => void;
}

export function QuoteActions({ quote, projectId, onQuoteUpdate }: QuoteActionsProps) {
  const { user } = useAuth();
  const isAdmin = user?.role === "admin";

  const submitMutation = useSubmitQuote();
  const approveMutation = useApproveQuote();
  const sendMutation = useSendQuote();
  const respondMutation = useRespondQuote();
  const cloneMutation = useCloneQuote();

  return (
    <div className="flex flex-wrap gap-2">
      <Button variant="outline" size="sm" onClick={() => downloadQuotePdf(quote.id)}>
        Download PDF
      </Button>
      {quote.status === "draft" && (
        <Button size="sm" onClick={async () => { await submitMutation.mutateAsync({ quoteId: quote.id, projectId }); onQuoteUpdate?.(); }} disabled={submitMutation.isPending}>
          Submit for Approval
        </Button>
      )}
      {quote.status === "pending_approval" && isAdmin && (
        <>
          <Button size="sm" onClick={async () => { await approveMutation.mutateAsync({ quoteId: quote.id, projectId }); onQuoteUpdate?.(); }} disabled={approveMutation.isPending}>
            Approve
          </Button>
          <Button size="sm" variant="outline" onClick={async () => { await respondMutation.mutateAsync({ quoteId: quote.id, projectId, response: "rejected" }); onQuoteUpdate?.(); }} disabled={respondMutation.isPending}>
            Reject to Draft
          </Button>
        </>
      )}
      {quote.status === "approved" && (
        <Button size="sm" onClick={async () => { await sendMutation.mutateAsync({ quoteId: quote.id, projectId }); onQuoteUpdate?.(); }} disabled={sendMutation.isPending}>
          Send to Client
        </Button>
      )}
      {quote.status === "sent" && (
        <>
          <Button size="sm" onClick={async () => { await respondMutation.mutateAsync({ quoteId: quote.id, projectId, response: "accepted" }); onQuoteUpdate?.(); }} disabled={respondMutation.isPending}>
            Accept
          </Button>
          <Button size="sm" variant="destructive" onClick={async () => { await respondMutation.mutateAsync({ quoteId: quote.id, projectId, response: "rejected" }); onQuoteUpdate?.(); }} disabled={respondMutation.isPending}>
            Reject
          </Button>
        </>
      )}
      {quote.status === "rejected" && (
        <Button size="sm" onClick={async () => { await cloneMutation.mutateAsync({ quoteId: quote.id, projectId }); onQuoteUpdate?.(); }} disabled={cloneMutation.isPending}>
          Clone to Draft
        </Button>
      )}
    </div>
  );
}

import { useQuote } from "@/hooks/useQuotes";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { QuoteActions } from "./QuoteActions";
import { QuoteStatus } from "@/types/api";

const STATUS_COLORS: Record<QuoteStatus, string> = {
  draft: "bg-gray-100 text-gray-800",
  pending_approval: "bg-yellow-100 text-yellow-800",
  approved: "bg-blue-100 text-blue-800",
  sent: "bg-purple-100 text-purple-800",
  accepted: "bg-green-100 text-green-800",
  rejected: "bg-red-100 text-red-800",
};

const STATUS_TIMELINE = ["draft", "pending_approval", "approved", "sent", "accepted"] as const;

interface QuoteDetailProps {
  quoteId: string;
  projectId: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function QuoteDetail({ quoteId, projectId, open, onOpenChange }: QuoteDetailProps) {
  const { data: quote, isLoading, refetch } = useQuote(quoteId);

  if (!quote) return null;

  const currentIndex = STATUS_TIMELINE.indexOf(quote.status as typeof STATUS_TIMELINE[number]);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-3">
            Quote #{quote.version_number}
            <span className={`px-2 py-1 rounded text-xs font-medium ${STATUS_COLORS[quote.status]}`}>
              {quote.status.replace("_", " ")}
            </span>
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-6">
          <Card>
            <CardHeader><CardTitle>Status Timeline</CardTitle></CardHeader>
            <CardContent>
              <div className="flex items-center gap-2">
                {STATUS_TIMELINE.map((status, i) => (
                  <div key={status} className="flex items-center gap-2">
                    <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium ${i <= currentIndex ? "bg-green-600 text-white" : "bg-gray-200 text-gray-500"}`}>
                      {i + 1}
                    </div>
                    <span className="text-sm capitalize">{status.replace("_", " ")}</span>
                    {i < STATUS_TIMELINE.length - 1 && (
                      <div className={`w-8 h-0.5 ${i < currentIndex ? "bg-green-600" : "bg-gray-200"}`} />
                    )}
                  </div>
                ))}
                {quote.status === "rejected" && (
                  <div className="ml-2 px-2 py-1 rounded text-xs font-medium bg-red-100 text-red-800">Rejected</div>
                )}
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader><CardTitle>Totals</CardTitle></CardHeader>
            <CardContent className="space-y-2">
              <div className="flex justify-between"><span>Subtotal</span><span>₹{quote.subtotal.toLocaleString()}</span></div>
              <div className="flex justify-between"><span>Markup ({quote.markup_percent}%)</span><span>₹{quote.markup_amount.toLocaleString()}</span></div>
              <div className="flex justify-between"><span>Tax ({quote.tax_percent}%)</span><span>₹{quote.tax_amount.toLocaleString()}</span></div>
              <div className="flex justify-between font-bold text-lg border-t pt-2"><span>Total</span><span>₹{quote.total_amount.toLocaleString()}</span></div>
              {quote.valid_until && <div className="mt-4 text-sm text-muted-foreground">Valid until: {new Date(quote.valid_until).toLocaleDateString()}</div>}
            </CardContent>
          </Card>

          {quote.terms && (
            <Card>
              <CardHeader><CardTitle>Terms & Conditions</CardTitle></CardHeader>
              <CardContent><p className="text-sm whitespace-pre-wrap">{quote.terms}</p></CardContent>
            </Card>
          )}

          <Card>
            <CardHeader><CardTitle>Quote Actions</CardTitle></CardHeader>
            <CardContent><QuoteActions quote={quote} projectId={projectId} onQuoteUpdate={refetch} /></CardContent>
          </Card>
        </div>
      </DialogContent>
    </Dialog>
  );
}

